/**
 * `item/BagItem.java` and `item/BagMenus.java`: item inventories (ADR 0095 D1 to D3, D6) as the
 * runtime's `registry/inventory/` classes are specified (`MsmInventoryItem`, the three menu
 * subclasses and `BagGuard`; B440 S10, B450), written from the ADR: the contents live in the
 * stack's `minecraft:container` component, written whenever they change and once more on close;
 * 27 slots open a `ShulkerBoxMenu`, other sizes `ChestMenu`, `HopperMenu` or `DispenserMenu`
 * subclasses; the guard refuses clicks on the open bag's own slot, number-key and off-hand swaps
 * onto it, puts back anything that cannot go inside a container item (bags, shulker boxes,
 * bundles), and closes the menu when the stack in the opening hand is no longer the same stack.
 * A bag fits in no container item. Minecraft 26.3, Mojang names.
 *
 * @packageDocumentation
 */

/** The source of `<package>.item.BagItem`. */
export function bagItemJava(itemPackage: string): string {
  return `// Generated by MCSuperMods: msm:item_inventory of msm_runtime (registry/inventory, ADR 0095) as a plain class.
package ${itemPackage};

import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.MenuType;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;

/**
 * A bag (ADR 0095 D1): using it (or sneak-using it, with {@code open: sneak_use}) opens a vanilla screen of its own
 * slots. It fits inside no container item, so shulker boxes, bundles and other bags refuse it.
 */
public class BagItem extends Item {
    /** The screen a bag opens. */
    public enum Layout {
        CHEST,
        HOPPER,
        DISPENSER
    }

    private final Layout layout;
    private final int rows;
    private final boolean sneakUse;
    private final Identifier openSound;
    private final Identifier closeSound;

    /**
     * @param rows rows of nine with the chest layout, 1 to 6
     * @param openSound the sound played on opening, or null for a barrel's
     * @param closeSound the sound played on closing, or null for a barrel's
     */
    public BagItem(Properties properties, Layout layout, int rows, boolean sneakUse, Identifier openSound, Identifier closeSound) {
        super(properties);
        this.layout = layout;
        this.rows = Math.max(1, Math.min(6, rows));
        this.sneakUse = sneakUse;
        this.openSound = openSound;
        this.closeSound = closeSound;
    }

    /** The number of slots. */
    public int size() {
        return switch (layout) {
            case CHEST -> rows * 9;
            case HOPPER -> 5;
            case DISPENSER -> 9;
        };
    }

    @Override
    public boolean canFitInsideContainerItems() {
        return false;
    }

    @Override
    public InteractionResult use(Level level, Player player, InteractionHand hand) {
        if (player.isSecondaryUseActive() != sneakUse) {
            return super.use(level, player, hand);
        }
        ItemStack stack = player.getItemInHand(hand);
        if (level instanceof ServerLevel server && player instanceof ServerPlayer serverPlayer) {
            BagMenus.Bag bag = new BagMenus.Bag(this, stack, hand, size());
            serverPlayer.openMenu(new SimpleMenuProvider((id, inventory, p) -> menu(id, inventory, bag), stack.getHoverName()));
            play(server, serverPlayer, openSound, SoundEvents.BARREL_OPEN);
            onOpened(server, serverPlayer);
        }
        return InteractionResult.SUCCESS;
    }

    private AbstractContainerMenu menu(int id, Inventory inventory, BagMenus.Bag bag) {
        return switch (layout) {
            case CHEST -> rows == 3 ? new BagMenus.Shulker(id, inventory, bag) : new BagMenus.Chest(chestType(), id, inventory, bag, rows);
            case HOPPER -> new BagMenus.Hopper(id, inventory, bag);
            case DISPENSER -> new BagMenus.Dispenser(id, inventory, bag);
        };
    }

    private MenuType<?> chestType() {
        return switch (rows) {
            case 1 -> MenuType.GENERIC_9x1;
            case 2 -> MenuType.GENERIC_9x2;
            case 4 -> MenuType.GENERIC_9x4;
            case 5 -> MenuType.GENERIC_9x5;
            case 6 -> MenuType.GENERIC_9x6;
            default -> MenuType.GENERIC_9x3;
        };
    }

    /** Called by the menu once it has closed and the contents are written. */
    void closed(ServerPlayer player) {
        if (player.level() instanceof ServerLevel server) {
            play(server, player, closeSound, SoundEvents.BARREL_CLOSE);
            onClosed(server, player);
        }
    }

    private static void play(ServerLevel level, ServerPlayer player, Identifier id, SoundEvent fallback) {
        SoundEvent sound = id == null ? fallback : BuiltInRegistries.SOUND_EVENT.getValue(id);
        if (sound != null) {
            level.playSound(null, player.blockPosition(), sound, SoundSource.PLAYERS, 1.0f, 1.0f);
        }
    }

    /** After the bag opens ({@code on_open}); nothing here. */
    protected void onOpened(ServerLevel level, ServerPlayer player) {}

    /** After the bag closes ({@code on_close}); nothing here. */
    protected void onClosed(ServerLevel level, ServerPlayer player) {}
}
`;
}

/** The source of `<package>.item.BagMenus`. */
export function bagMenusJava(itemPackage: string): string {
  return `// Generated by MCSuperMods: the bag menus and their guard (ADR 0095 D2, D3) as plain classes.
package ${itemPackage};

import net.minecraft.core.component.DataComponents;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.Prediction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.ChestMenu;
import net.minecraft.world.inventory.ContainerInput;
import net.minecraft.world.inventory.DispenserMenu;
import net.minecraft.world.inventory.HopperMenu;
import net.minecraft.world.inventory.MenuType;
import net.minecraft.world.inventory.ShulkerBoxMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.ItemContainerContents;

/**
 * The menus a bag opens and the guard they share (ADR 0095 D2, D3): no menu constructs a slot of its own. While the
 * menu is open the bag's slot is locked (clicks, number-key and off-hand swaps that touch it are refused), anything
 * that cannot go inside a container item is put back into the player's inventory, and the menu closes when the stack
 * in the opening hand is no longer the bag (dropped, moved by a command, the player died). The contents are written to
 * the stack's container component whenever they change and once more on close. A player in creative who picks the bag
 * again gets a copy with the contents as last written, as with shulker boxes.
 */
public final class BagMenus {
    private BagMenus() {}

    /** One open bag: its slots, read from and written to the stack. */
    public static final class Bag extends SimpleContainer {
        private final BagItem item;
        private final ItemStack stack;
        private final InteractionHand hand;
        private boolean closed;

        Bag(BagItem item, ItemStack stack, InteractionHand hand, int size) {
            super(size);
            this.item = item;
            this.stack = stack;
            this.hand = hand;
            stack.getOrDefault(DataComponents.CONTAINER, ItemContainerContents.EMPTY).copyInto(getItems());
        }

        @Override
        public void setChanged() {
            super.setChanged();
            write();
        }

        private void write() {
            stack.set(DataComponents.CONTAINER, ItemContainerContents.fromItems(getItems()));
        }

        /** Whether the stack in the opening hand is still this bag. */
        @Override
        public boolean stillValid(Player player) {
            return !stack.isEmpty() && player.getItemInHand(hand) == stack;
        }

        /** Whether a click would move the bag itself: on its slot, or a number-key or off-hand swap onto it. */
        boolean refuses(net.minecraft.world.inventory.AbstractContainerMenu menu, int slot, int button, ContainerInput input,
                Player player) {
            if (slot >= 0 && slot < menu.slots.size() && menu.slots.get(slot).getItem() == stack) {
                return true;
            }
            if (input == ContainerInput.SWAP) {
                int index = button == 40 ? Inventory.SLOT_OFFHAND : button;
                return index >= 0 && player.getInventory().getItem(index) == stack;
            }
            return false;
        }

        /** Puts back into the player's inventory anything that cannot go inside a container item. */
        void cleanUp(Player player) {
            for (int i = 0; i < getContainerSize(); i++) {
                ItemStack inside = getItem(i);
                if (!inside.isEmpty() && (!inside.getItem().canFitInsideContainerItems() || inside == stack)) {
                    setItem(i, ItemStack.EMPTY);
                    player.getInventory().placeItemBackInInventory(inside, Prediction.SERVER_ONLY);
                }
            }
        }

        void close(Player player) {
            if (closed) {
                return;
            }
            closed = true;
            write();
            if (player instanceof ServerPlayer serverPlayer) {
                item.closed(serverPlayer);
            }
        }
    }

    /** 27 slots: vanilla's shulker box screen, whose slots already refuse container items. */
    public static final class Shulker extends ShulkerBoxMenu {
        private final Bag bag;

        Shulker(int id, Inventory inventory, Bag bag) {
            super(id, inventory, bag);
            this.bag = bag;
        }

        @Override
        public void clicked(int slot, int button, ContainerInput input, Player player) {
            if (!bag.refuses(this, slot, button, input, player)) {
                super.clicked(slot, button, input, player);
                bag.cleanUp(player);
            }
        }

        @Override
        public boolean stillValid(Player player) {
            return bag.stillValid(player);
        }

        @Override
        public void removed(Player player) {
            super.removed(player);
            bag.close(player);
        }
    }

    /** 9, 18, 36, 45 or 54 slots. */
    public static final class Chest extends ChestMenu {
        private final Bag bag;

        Chest(MenuType<?> type, int id, Inventory inventory, Bag bag, int rows) {
            super(type, id, inventory, bag, rows);
            this.bag = bag;
        }

        @Override
        public void clicked(int slot, int button, ContainerInput input, Player player) {
            if (!bag.refuses(this, slot, button, input, player)) {
                super.clicked(slot, button, input, player);
                bag.cleanUp(player);
            }
        }

        @Override
        public boolean stillValid(Player player) {
            return bag.stillValid(player);
        }

        @Override
        public void removed(Player player) {
            super.removed(player);
            bag.close(player);
        }
    }

    /** Five slots, as a hopper. */
    public static final class Hopper extends HopperMenu {
        private final Bag bag;

        Hopper(int id, Inventory inventory, Bag bag) {
            super(id, inventory, bag);
            this.bag = bag;
        }

        @Override
        public void clicked(int slot, int button, ContainerInput input, Player player) {
            if (!bag.refuses(this, slot, button, input, player)) {
                super.clicked(slot, button, input, player);
                bag.cleanUp(player);
            }
        }

        @Override
        public boolean stillValid(Player player) {
            return bag.stillValid(player);
        }

        @Override
        public void removed(Player player) {
            super.removed(player);
            bag.close(player);
        }
    }

    /** Three by three slots, as a dispenser. */
    public static final class Dispenser extends DispenserMenu {
        private final Bag bag;

        Dispenser(int id, Inventory inventory, Bag bag) {
            super(id, inventory, bag);
            this.bag = bag;
        }

        @Override
        public void clicked(int slot, int button, ContainerInput input, Player player) {
            if (!bag.refuses(this, slot, button, input, player)) {
                super.clicked(slot, button, input, player);
                bag.cleanUp(player);
            }
        }

        @Override
        public boolean stillValid(Player player) {
            return bag.stillValid(player);
        }

        @Override
        public void removed(Player player) {
            super.removed(player);
            bag.close(player);
        }
    }
}
`;
}
